/* eslint-env mocha */
/* eslint-disable import/no-unresolved */
const expect = require('chai').expect;
const sinon = require('sinon');
describe('A test', () => {
  it('should run', () => {
    expect(true).to.be.true;
  });
  it('should run with a spy', () => {
    const faker = sinon.spy();
    faker();
    expect(faker.called).to.be.true;
  });
});